const cfg = $json || {};
const raw = cfg.body && typeof cfg.body === 'object' ? cfg.body : cfg;

const locationId = String(cfg.locationId || '').trim();
const apiBaseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String(cfg.apiKey || '').trim();
const rb2bTag = String(cfg.rb2bTag || 'rb2b_website_visitor').trim();

if (!locationId) throw new Error('Missing GHL locationId');
if (!apiKey) throw new Error('Missing GHL apiKey');

const get = (key) => {
  const value = raw?.[key];
  return value === undefined || value === null ? '' : String(value).trim();
};

const cleanLower = (v) => String(v || '').trim().toLowerCase();
const normalizeSpace = (v) => String(v || '').trim().replace(/\s+/g, ' ');

const lead = {
  linkedin_url: get('LinkedIn URL'),
  first_name: get('First Name'),
  last_name: get('Last Name'),
  title: get('Title'),
  company_name: get('Company Name'),
  business_email: cleanLower(get('Business Email')),
  phone: get('Phone'),
  website: get('Website'),
  industry: get('Industry'),
  employee_count: get('Employee Count'),
  estimate_revenue: get('Estimate Revenue'),
  city: get('City'),
  state: get('State'),
  zipcode: get('Zipcode'),
  seen_at_raw: get('Seen At'),
  referrer: get('Referrer'),
  captured_url: get('Captured URL'),
  source_tags: get('Tags'),
};

const fullName = normalizeSpace(`${lead.first_name} ${lead.last_name}`);
if (!lead.business_email && !lead.phone && !fullName) {
  throw new Error('RB2B payload missing email, phone, and full name.');
}

const leadKey = lead.business_email
  ? `email:${lead.business_email}`
  : lead.phone
    ? `phone:${lead.phone}`
    : `name:${cleanLower(fullName)}|company:${cleanLower(lead.company_name)}`;

const headers = {
  Authorization: `Bearer ${apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest(method, path, body) {
  const options = { method, url: `${apiBaseUrl}${path}`, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return { ok: false, data: err?.response?.body || err?.message || err };
  }
}

function extractContactId(payload) {
  return String(payload?.contact?.id || payload?.id || payload?.contactId || '').trim();
}

function asArrayContacts(payload) {
  if (Array.isArray(payload?.contacts)) return payload.contacts;
  if (Array.isArray(payload?.data?.contacts)) return payload.data.contacts;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload)) return payload;
  return [];
}

let ghlContactId = '';
let ghlMatchMethod = 'none';

if (lead.business_email) {
  const dup = await apiRequest.call(this, 'GET', `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&email=${encodeURIComponent(lead.business_email)}`);
  if (dup.ok && dup.data?.contact?.id) {
    ghlContactId = String(dup.data.contact.id);
    ghlMatchMethod = 'email_duplicate';
  }
}

if (!ghlContactId && lead.phone) {
  const dup = await apiRequest.call(this, 'GET', `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&number=${encodeURIComponent(lead.phone)}`);
  if (dup.ok && dup.data?.contact?.id) {
    ghlContactId = String(dup.data.contact.id);
    ghlMatchMethod = 'phone_duplicate';
  }
}

if (!ghlContactId && fullName) {
  const byName = await apiRequest.call(this, 'GET', `/contacts/?locationId=${encodeURIComponent(locationId)}&query=${encodeURIComponent(fullName)}&limit=50`);
  if (byName.ok) {
    const contacts = asArrayContacts(byName.data);
    const target = cleanLower(fullName);
    const exact = contacts.find((c) => {
      const fn = normalizeSpace(`${c.firstName || ''} ${c.lastName || ''}`);
      const nm = normalizeSpace(c.name || '');
      return cleanLower(fn) === target || cleanLower(nm) === target;
    });
    if (exact?.id) {
      ghlContactId = String(exact.id);
      ghlMatchMethod = 'full_name';
    }
  }
}

const baseContactPayload = {
  firstName: lead.first_name || undefined,
  lastName: lead.last_name || undefined,
  name: fullName || undefined,
  email: lead.business_email || undefined,
  phone: lead.phone || undefined,
  companyName: lead.company_name || undefined,
  website: lead.website || undefined,
  city: lead.city || undefined,
  state: lead.state || undefined,
  postalCode: lead.zipcode || undefined,
  source: 'RB2B Website Visitor',
};

if (ghlContactId) {
  const updateResp = await apiRequest.call(this, 'PUT', `/contacts/${ghlContactId}`, baseContactPayload);
  if (!updateResp.ok) throw new Error(`Failed to update GHL contact ${ghlContactId}: ${JSON.stringify(updateResp.data)}`);
} else if (lead.business_email || lead.phone) {
  const upsertResp = await apiRequest.call(this, 'POST', '/contacts/upsert', { locationId, ...baseContactPayload });
  if (!upsertResp.ok) throw new Error(`Failed to upsert GHL contact: ${JSON.stringify(upsertResp.data)}`);
  ghlContactId = extractContactId(upsertResp.data);
  if (!ghlContactId) throw new Error(`GHL upsert returned no contact id: ${JSON.stringify(upsertResp.data)}`);
  ghlMatchMethod = 'upsert_create_or_update';
} else {
  const createResp = await apiRequest.call(this, 'POST', '/contacts/', { locationId, ...baseContactPayload });
  if (!createResp.ok) throw new Error(`Failed to create GHL contact without unique identifier: ${JSON.stringify(createResp.data)}`);
  ghlContactId = extractContactId(createResp.data);
  if (!ghlContactId) throw new Error(`GHL create returned no contact id: ${JSON.stringify(createResp.data)}`);
  ghlMatchMethod = 'create_without_unique_identifier';
}

const tagList = Array.from(new Set([rb2bTag, 'mql']));
const tagResp = await apiRequest.call(this, 'POST', `/contacts/${ghlContactId}/tags`, { tags: tagList });
if (!tagResp.ok) throw new Error(`Failed adding tag ${rb2bTag}: ${JSON.stringify(tagResp.data)}`);

return [{
  json: {
    ok: true,
    location_id: locationId,
    lead_key: leadKey,
    ghl_contact_id: ghlContactId,
    ghl_match_method: ghlMatchMethod,
    rb2b_tag_applied: rb2bTag,
    ...lead,
  },
}];

